  `pegawai_id` bigint(20) NULL DEFAULT NULL,
  `penerima_id` int(11) NULL DEFAULT NULL,
  `nama_penerima` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `no_rekening` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `npwp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `skema_pajak_id` int(11) NULL DEFAULT NULL,
  `uraian` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `komponen_pd` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `volume` decimal(15, 2) NOT NULL DEFAULT 1,
  `harga_satuan` decimal(20, 2) NOT NULL DEFAULT 0,
  `jumlah` decimal(20, 2) NOT NULL DEFAULT 0,
  `keterangan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `created_at` datetime(0) NULL DEFAULT current_timestamp(0),
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_np_detail`(`npd_detail_id`) USING BTREE,
  INDEX `idx_np_penerima`(`penerima_id`) USING BTREE,
  INDEX `idx_np_pegawai`(`pegawai_id`) USING BTREE,
  CONSTRAINT `fk_np_detail` FOREIGN KEY (`npd_detail_id`) REFERENCES `npd_detail` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_np_pegawai` FOREIGN KEY (`pegawai_id`) REFERENCES `pegawai` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_np_penerima` FOREIGN KEY (`penerima_id`) REFERENCES `master_penerima` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

