-- ----------------------------
-- Table structure for pegawai
-- ----------------------------
DROP TABLE IF EXISTS `pegawai`;
CREATE TABLE `pegawai`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `nama_lengkap` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `jenis_kelamin` enum('L','P') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `tgl_lahir` date NULL DEFAULT NULL,
  `tgl_cpns` date NULL DEFAULT NULL,
  `tgl_pns` date NULL DEFAULT NULL,
  `status_kepegawaian` enum('ASN','NON_ASN') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `jenis_kepegawaian` enum('PNS','CPNS','PPPK','NON_ASN') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `nip` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `golongan` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `pangkat` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `status_pernikahan` enum('BELUM_KAWIN','KAWIN','JANDA','DUDA') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'BELUM_KAWIN',
  `jumlah_anak` tinyint(3) UNSIGNED NULL DEFAULT 0,
  `terima_tunjangan_keluarga` tinyint(1) NOT NULL DEFAULT 1,
  `masa_kerja_golongan` tinyint(3) UNSIGNED NULL DEFAULT 0,
  `tmt_kenaikan_pangkat` date NULL DEFAULT NULL,
  `tmt_kgb` date NULL DEFAULT NULL COMMENT 'TMT KGB Berikutnya (fallback jika tgl_pns tidak diisi)',
  `jabatan_struktural_id` bigint(20) NULL DEFAULT NULL,
  `jabatan_penatausahaan_id` bigint(20) NULL DEFAULT NULL,
  `jabatan_fungsional_id` bigint(20) NULL DEFAULT NULL,
  `ref_tpp_id` int(11) NULL DEFAULT NULL,
  `kd_jabatan_fungsional` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `kd_tunjangan_khusus` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `persen_gaji` tinyint(3) UNSIGNED NOT NULL DEFAULT 100 COMMENT '100=normal, 80=CPNS, 50=hudis',
  `npwp` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `opd_id` int(11) NOT NULL,
  `opd_unit_id` int(11) NULL DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime(0) NOT NULL DEFAULT current_timestamp(0),
  `updated_at` datetime(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pegawai_nip`(`nip`) USING BTREE,
  INDEX `fk_pegawai_opd`(`opd_id`) USING BTREE,
  INDEX `fk_pegawai_opd_unit`(`opd_unit_id`) USING BTREE,
  CONSTRAINT `fk_pegawai_opd` FOREIGN KEY (`opd_id`) REFERENCES `master_opd` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pegawai_opd_unit` FOREIGN KEY (`opd_unit_id`) REFERENCES `master_opd_unit` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

