  INDEX `fk_pj_opd_unit`(`opd_unit_id`) USING BTREE,
  CONSTRAINT `fk_pj_jabatan` FOREIGN KEY (`jabatan_id`) REFERENCES `ref_jabatan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
