INSERT INTO `master_skema_pajak` VALUES (1, 'HONOR', 'PPh 21 Honorarium', 'honorarium', 'Honorarium: PPh 21 final utk PNS per golongan; non-PNS tarif Ps.17 (+20% tanpa NPWP).', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (2, 'BARANG', 'Belanja Barang', 'barang', 'PPh 22 (1,5%/3%) + PPN 11% bila PKP & DPP > 2 juta.', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (3, 'JASA', 'Belanja Jasa', 'jasa', 'PPh 23 (2%/4%) + PPN 11% bila PKP.', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (4, 'JASA_BOGA', 'Jasa Boga / Katering', 'jasa_boga', 'PPh 23 (2%/4%) atas jasa boga; DIKECUALIKAN dari PPN.', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (5, 'SEWA', 'Sewa', 'sewa', 'Sewa selain tanah/bangunan: PPh 23 2%/4%. CATATAN: sewa tanah/bangunan = PPh Ps.4(2) 10% final (ubah bila berlaku).', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (6, 'KONSTRUKSI', 'Jasa Konstruksi', 'konstruksi', 'PPh Ps.4(2) final (tarif tergantung kualifikasi) + PPN 11%. Angka draft, sesuaikan.', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (7, 'MODAL', 'Belanja Modal', 'modal', 'Sama seperti barang: PPh 22 (1,5%/3%) + PPN 11% (barang). Konstruksi/konsultan diklasifikasi terpisah.', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (8, 'MAKMIN', 'Makan & Minum', 'makan_minum', 'Umumnya tanpa potongan bendahara; pajak restoran (PB1) sudah termasuk harga. Sesuaikan bila perlu.', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (9, 'PERJADIN', 'Perjalanan Dinas', 'perjalanan_dinas', 'Umumnya tanpa pemotongan (lumpsum/at cost).', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (10, 'PEGAWAI', 'Belanja Pegawai / Gaji', 'pegawai', 'Gaji/tunjangan: PPh 21 diproses pada daftar gaji (di luar mekanisme pinbuk ini).', 1, '2026-07-30 15:39:05');
INSERT INTO `master_skema_pajak` VALUES (11, 'NONPAJAK', 'Tanpa Pemotongan Pajak', 'non_pajak', 'Bukan objek pemotongan pajak.', 1, '2026-07-30 15:39:05');
